// T5 glue between the DriverKit classes and the shared translator (Shared/GDHubXlate.c): the self-test and the validation of
// a pushed mapping. Plain C++ over the registry; no iig class is touched and nothing here holds a lock across a call.
#include "GDHubInternal.h"
#include "GDHubVirtualHIDUserClient.h"      // generated: the class is an OSObject for the static_cast
#include "GDHubXlate.h"
#include "GDHubDefaults.h"        // the factory GDHM blob, its pad spec and the 64 golden vectors (generated by a Swift test)

static_assert(sizeof(gdx_map) <= GDH_MAP_MAX, "a validated mapping must fit the registry's handoff buffer");
static_assert(GDX_BLOB_MAX <= GDH_MAP_MAX, "and so must any blob");

// The golden vectors through THIS build of the core: eval + build + step must give the bytes the Swift oracle gave. This proves
// the dext's compiled code (optimisation level, FMA contraction, library differences) on the cases the vectors cover. Three
// sets of 64: the factory mapping (no learned ranges) and two learned-range mappings (A: symmetric full int16 range on all four
// axes, B: one asymmetric range per axis), so the ranged division of the axis normalisation runs too.
// Bounded: 3 validates and 3 x 64 vectors, each one eval + build + two steps (~5 calls of a few hundred ns to a few us); a loop of
// fixed trip counts, no allocation, about 1 ms at most (the Swift benchmark measures the whole pipeline at a few us per frame).
static bool runSet(const uint8_t * blob, size_t blobLen, const uint8_t * golden, uint32_t count, uint32_t base, uint32_t * failed)
{
    gdx_map m;
    memset(&m, 0, sizeof(m));
    int rc = gdx_validate(blob, blobLen, GDX_DEFAULT_SPEC, sizeof(GDX_DEFAULT_SPEC), &m);
    if (rc != GDX_OK) { *failed = 1000 + base + (uint32_t)rc; return false; }
    for (uint32_t v = 0; v < count; v++) {
        const uint8_t * g = golden + v * GDX_GOLDEN_STRIDE;
        gdx_pad pad;
        gdx_out out;
        if (gdx_eval(&m, g, 16, &pad) != 0) { *failed = base + v; return false; }
        gdx_build(&m, &pad, &out);
        if (out.count < 2 || out.r[0].len != 16 || out.r[1].len != 2 ||
            memcmp(out.r[0].bytes, g + 16, 16) != 0 || memcmp(out.r[1].bytes, g + 32, 2) != 0) { *failed = base + v; return false; }
        // gdx_step on a fresh state posts both reports with the same bytes, and the same frame again posts nothing
        gdx_state st;
        gdx_reset(&st);
        gdx_out sout;
        uint32_t mask = gdx_step(&st, &m, g, 16, &sout);
        if (mask != 3u || sout.count < 2 || sout.r[0].len != 16 || sout.r[1].len != 2 ||
            memcmp(sout.r[0].bytes, g + 16, 16) != 0 || memcmp(sout.r[1].bytes, g + 32, 2) != 0) { *failed = 2000 + base + v; return false; }
        if (gdx_step(&st, &m, g, 16, &sout) != 0u) { *failed = 3000 + base + v; return false; }
    }
    return true;
}

static bool runSelfTest(uint32_t * failedVector)
{
    static_assert(GDX_LEARNED_GOLDEN_COUNT == GDX_GOLDEN_COUNT, "the three sets use the same frames");
    return runSet(GDX_DEFAULT_BLOB, sizeof(GDX_DEFAULT_BLOB), GDX_GOLDEN, GDX_GOLDEN_COUNT, 0, failedVector) &&
           runSet(GDX_LEARNED_A_BLOB, sizeof(GDX_LEARNED_A_BLOB), GDX_LEARNED_A_GOLDEN, GDX_LEARNED_GOLDEN_COUNT, 100, failedVector) &&
           runSet(GDX_LEARNED_B_BLOB, sizeof(GDX_LEARNED_B_BLOB), GDX_LEARNED_B_GOLDEN, GDX_LEARNED_GOLDEN_COUNT, 200, failedVector);
}

// Runs once per process, on the first SHADOW request of the OWNER (selector 9, on the root's queue). Never from a tap Start, so an
// INERT or COUNT-only process executes no translator code at all. Returns the state: PASS, FAIL, or RUNNING (only if some other
// thread were mid-test, which the serial root queue rules out; the caller then answers NotReady and the engine asks again).
uint32_t GDHubSelfTestEnsure(void)
{
    gdhr * reg = GDHubReg();
    if (!reg) return GDHR_SELFTEST_FAIL;
    if (gdhr_selftest_begin(reg)) {
        uint32_t bad = 0;
        bool ok = runSelfTest(&bad);
        gdhr_selftest_finish(reg, ok ? 1 : 0);
        if (ok) GDLog("selftest pass vectors=%u build=%u", (unsigned)(GDX_GOLDEN_COUNT + 2 * GDX_LEARNED_GOLDEN_COUNT), (unsigned)GDHUB_DEXT_BUILD);
        else GDLog("selftest FAIL vector=%u build=%u: SHADOW is refused for this process", bad, (unsigned)GDHUB_DEXT_BUILD);
    }
    return gdhr_selftest_get(reg);
}

// Selector 10. Every byte of `bytes` is validated by gdx_validate (which bounds-checks, CRC-checks and never reads outside
// [bytes, bytes + len)) against the CURRENT pad's spec before anything is stored; only a complete gdx_map is published, and
// only for the current owner. Returns kIOReturnSuccess when the request was understood (look at *reason: 0 = accepted, else
// a GDX_E_* code or a GDHUB_MAP_* code), kIOReturnBadArgument for a size outside the blob limits, kIOReturnNotPermitted for a
// caller that is not the owner. The previous mapping stays in every refusal.
kern_return_t GDHubMapAccept(GDHubVirtualHIDUserClient * uc, const uint8_t * bytes, size_t len, uint32_t * acceptedRevision, uint32_t * reason)
{
    gdhr * reg = GDHubReg();
    *acceptedRevision = 0;
    *reason = GDHUB_MAP_NO_REGISTRY;
    if (!reg) return kIOReturnNotReady;
    if (!bytes || len < GDX_BLOB_HEADER_SIZE || len > GDX_BLOB_MAX) return kIOReturnBadArgument;     // rule B: wrong sizes are rejected first
    if (gdhr_pad_state(reg) != GDHR_PAD_LIVE) { *reason = GDHUB_MAP_NO_PAD; gdhr_ctr_add(reg, GDHR_CTR_MAP_REFUSED, 1); return kIOReturnSuccess; }
    OSData * spec = GDHubCopyPadSpec();                                   // +1 of the live pad's spec
    if (!spec) { *reason = GDHUB_MAP_NO_PAD; gdhr_ctr_add(reg, GDHR_CTR_MAP_REFUSED, 1); return kIOReturnSuccess; }
    gdx_map map;
    memset(&map, 0, sizeof(map));
    int rc = gdx_validate(bytes, len, (const uint8_t *)spec->getBytesNoCopy(), spec->getLength(), &map);
    spec->release();
    if (rc != GDX_OK) { *reason = (uint32_t)rc; gdhr_ctr_add(reg, GDHR_CTR_MAP_REFUSED, 1); return kIOReturnSuccess; }
    int pub = gdhr_map_publish(reg, static_cast<OSObject *>(uc), &map, sizeof(map), map.revision, map.specCRC);
    switch (pub) {
    case GDHR_OK:
        gdhr_ctr_add(reg, GDHR_CTR_MAP_ACCEPTED, 1);
        *acceptedRevision = map.revision;
        *reason = GDHUB_MAP_OK;
        return kIOReturnSuccess;
    case GDHR_E_NOT_OWNER: gdhr_ctr_add(reg, GDHR_CTR_MAP_REFUSED, 1); return kIOReturnNotPermitted;
    case GDHR_E_NO_PAD:    *reason = GDHUB_MAP_NO_PAD; break;                 // the pad went away between the check and the publish
    case GDHR_E_SPEC:      *reason = GDX_E_SPEC_CRC; break;                   // and was replaced by one with another spec
    case GDHR_E_SIZE:      *reason = GDHUB_MAP_TOO_BIG; break;
    default:               *reason = GDHUB_MAP_NO_REGISTRY; break;
    }
    gdhr_ctr_add(reg, GDHR_CTR_MAP_REFUSED, 1);
    return kIOReturnSuccess;
}
